const grade8ExtensionRows=grade8ExtensionOutline.trim().split('\n').filter(Boolean).map(line=>{const [unit,title,objective,review,skillTag,vocabulary]=line.split('\t');return {unit,title,objective,review,skillTag,vocabulary:vocabulary.split('|')}});
const curriculumRows=[...rows.slice(0,116),...grade8ExtensionRows];

function makeExplanation({ unit, title, objective, review, skillTag, vocabulary }) {
  const [term1, term2, term3] = vocabulary;
  return [
    `${title} belongs to the ${unit} portion of the Grade 8 sequence. ${objective} A strong historical conclusion identifies the people involved, the setting, and the choices or conditions that shaped the event. The vocabulary for this lesson—${term1}, ${term2}, and ${term3}—gives students precise language for describing evidence instead of relying on vague labels.`,
    `Practice this lesson as a ${skillTag} task. Start with the most relevant detail in a source, map, timeline, data display, or constitutional text. Then explain what that detail shows in its historical context and connect it to a larger pattern of power, geography, economics, rights, or change over time. ${review} This keeps the explanation anchored in evidence rather than in an unsupported opinion.`,
    `The lesson also prepares students to make careful comparisons. Ask whose perspective is visible, whose perspective may be missing, and which consequence followed for different groups. A complete response names a specific fact, explains why it matters, and acknowledges limits or complexity when the evidence calls for it. That habit makes later work in United States history, civics, economics, and geography more accurate and more responsible.`
  ];
}

function makeExamples({ title, objective, review, skillTag, vocabulary }) {
  const [term1, term2, term3] = vocabulary;
  return [
    {
      prompt: `Use a short class source set about ${title} to make an evidence-based historical note.`,
      steps: [
        `Name the focus of the source set and restate the skill: ${objective}`,
        `Underline one detail connected to ${term1} or ${term2}, then identify the source's setting or perspective.`,
        `Write a claim that explains what the detail shows, using ${term3} precisely.`,
        `Check that the claim stays within the evidence rather than adding an unsupported conclusion.`
      ],
      answer: `A complete note identifies a specific source detail, explains it in context, and uses ${term1}, ${term2}, or ${term3} to support a careful claim about ${title}.`
    },
    {
      prompt: `Create a brief cause-and-consequence organizer for ${title}.`,
      steps: [
        `Record one condition or decision that led to the event, policy, movement, or pattern.`,
        `Add one piece of geographic, economic, civic, or historical evidence tied to ${term1}.`,
        `Explain one consequence for a named group, institution, or place using ${term2} or ${term3}.`,
        `End by connecting the organizer to this review idea: ${review}`
      ],
      answer: `The organizer should show a supported chain from a condition or decision to a consequence and should explain why ${title} matters beyond a single isolated fact.`
    }
  ];
}

export const historySequence = curriculumRows.map((lesson, index) => ({
  unit: lesson.unit,
  title: lesson.title,
  objective: lesson.objective,
  review: lesson.review,
  skillTags: [lesson.skillTag],
  prerequisites: curriculumRows.slice(index - 1, index).map((priorLesson) => priorLesson.title),
  vocabulary: lesson.vocabulary,
  explanation: makeExplanation(lesson),
  examples: makeExamples(lesson)
}));

if (historySequence.length !== 169) {
  throw new Error(`historySequence must contain 169 lessons; found ${historySequence.length}.`);
}

export default historySequence;
